package com.nextaicommerce.platform.receiving;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.web.servlet.mvc.support.RedirectAttributesModelMap;import java.math.BigDecimal;import java.util.UUID;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.assertj.core.api.Assertions.*;
class InventoryTransferConfirmationTest {
 @Test void confirmationOnlyFollowsCompletedExistingMove(){var repo=mock(InventoryRepository.class);var controller=new InventoryController(repo,null,null,null,null,null,null);var tenant=UUID.randomUUID();var session=new MockHttpSession();session.setAttribute("selectedTenantId",tenant);var flash=new RedirectAttributesModelMap();var nonce=UUID.randomUUID();
 doAnswer(call->{assertThat(flash.getFlashAttributes()).doesNotContainKey("inventoryTransferConfirmed");return null;}).when(repo).moveInventoryPosition(eq(tenant),anyString(),any(),any(),any(),any(),eq(BigDecimal.ONE),eq(false));
 assertThat(controller.moveLocation(new UsernamePasswordAuthenticationToken("owner","unused"),session,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,BigDecimal.ONE,false,nonce,flash)).isEqualTo("redirect:/app/inventory");assertThat(flash.getFlashAttributes().get("inventoryTransferRequest")).isEqualTo(nonce.toString());assertThat(flash.getFlashAttributes().get("inventoryTransferConfirmed")).isEqualTo(true);verify(repo,times(1)).moveInventoryPosition(eq(tenant),eq("owner"),any(),any(),any(),isNull(),eq(BigDecimal.ONE),eq(false));
 }
 @Test void rejectedMoveNeverConfirms(){var repo=mock(InventoryRepository.class);var controller=new InventoryController(repo,null,null,null,null,null,null);var session=new MockHttpSession();session.setAttribute("selectedTenantId",UUID.randomUUID());var flash=new RedirectAttributesModelMap();var nonce=UUID.randomUUID();doThrow(new IllegalArgumentException("Only available stock can move.")).when(repo).moveInventoryPosition(any(),anyString(),any(),any(),any(),any(),any(),anyBoolean());
 controller.moveLocation(new UsernamePasswordAuthenticationToken("owner","unused"),session,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,BigDecimal.ONE,false,nonce,flash);assertThat(flash.getFlashAttributes().get("inventoryTransferRequest")).isEqualTo(nonce.toString());assertThat(flash.getFlashAttributes().get("inventoryError")).isEqualTo("Only available stock can move.");assertThat(flash.getFlashAttributes()).doesNotContainKey("inventoryTransferConfirmed");
 }
}
